    'RegistrationText'=>'อินสแตนซ์ SimpleRisk ที่ลงทะเบียนแล้วจะได้รับสิทธิ์เข้าถึงส่วนเสริม Upgrade และ Secure Controls Framework (SCF) ทันที ส่วนเสริม Upgrade ช่วยให้คุณสามารถสำรองข้อมูลและอัปเกรดอินสแตนซ์ SimpleRisk ของคุณได้ด้วยการคลิกเพียงปุ่มเดียว ส่วนเสริม Secure Controls Framework (SCF) เป็นกรอบการควบคุมทั่วไปที่ผสานรวมเข้ากับฟังก์ชันการกำกับดูแลของ SimpleRisk เมื่อลงทะเบียน SimpleRisk ข้อมูลการลงทะเบียนของคุณจะถูกส่งไปยังเซิร์ฟเวอร์ที่โฮสต์โดย SimpleRisk ข้อมูลการลงทะเบียนที่ให้ไว้จะถูกใช้โดย SimpleRisk เพื่อแจ้งให้ลูกค้าทราบเกี่ยวกับการออกเวอร์ชันใหม่และการอัปเดตความปลอดภัย การลงทะเบียน SimpleRisk จะทำให้คุณได้รับข้อมูลการตลาดจากเรา แต่คุณสามารถยกเลิกการรับข้อมูลได้ตลอดเวลาโดยใช้ลิงก์ยกเลิกการสมัครรับข้อมูลในอีเมลเหล่านั้น SimpleRisk เคารพความเป็นส่วนตัวของลูกค้าของเรา และข้อมูลที่ให้ไว้กับเราผ่านกระบวนการลงทะเบียน SimpleRisk จะไม่ถูกขายให้กับบุคคลที่สาม',
