    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'กำหนดค่าการตั้งค่าทั่วทั้งระบบ: URL พื้นฐาน, ความปลอดภัย, ภาษาเริ่มต้น, เขตเวลา, ค่าเริ่มต้นของการให้คะแนนความเสี่ยง และอื่นๆ',
    'SettingsPreferencesDesc'             => 'ค่าเริ่มต้นและการตั้งค่าพฤติกรรมต่างๆ ใน SimpleRisk ได้แก่ ภาษา เขตเวลา สถานะการตรวจสอบ ข้อกำหนดการแมปความเสี่ยง การสลับพฤติกรรม UI และอื่นๆ ที่คล้ายกัน',
    'SettingsFileUploadDesc'              => 'ประเภทไฟล์ที่อนุญาตและขนาดไฟล์สูงสุดสำหรับช่องแนบไฟล์ต่างๆ',
    'SettingsMailDesc'                    => 'การกำหนดค่า SMTP สำหรับการแจ้งเตือนทางอีเมลขาออก รวมถึงวิธีการส่ง โฮสต์ การตรวจสอบสิทธิ์ และที่อยู่สำหรับตอบกลับ',
    'SettingsBackupsDesc'                 => 'กำหนดค่าการเก็บรักษาข้อมูลสำรอง กำหนดเวลา และลิงก์ดาวน์โหลดสำหรับข้อมูลสำรองฐานข้อมูล SimpleRisk',
    'SettingsSecurityDesc'                => 'การตรวจสอบสิทธิ์ เซสชัน นโยบายรหัสผ่าน URL พื้นฐาน และการตั้งค่าความปลอดภัยของ API',
    'SettingsLoggingDesc'                 => 'การกำหนดค่าการบันทึกข้อมูลการดีบักและการตรวจสอบ: ระดับการบันทึก ระยะเวลาการเก็บรักษา และตำแหน่งของไฟล์บันทึก',
    'HealthCheckDesc'                     => 'ตรวจสอบสถานะระบบ: เวอร์ชัน PHP, ส่วนขยาย, สิทธิ์การเข้าถึงไฟล์, การเชื่อมต่อฐานข้อมูล, กำหนดการ Cron และการเปิดใช้งานเพิ่มเติม',
    'AnnouncementsDesc'                   => 'สร้างและจัดการแบนเนอร์ประกาศที่ผู้ใช้ทุกคนสามารถมองเห็นได้',
    'RegisterAndUpgradeDesc'              => 'ลงทะเบียนการติดตั้ง SimpleRisk ของคุณ ป้อนหรือต่ออายุรหัสการสมัครใช้งาน และเริ่มการอัปเกรด Core/Extra ด้วยการคลิกเพียงครั้งเดียว',
    'QueueMonitorDesc'                    => 'ตรวจสอบคิวงานเบื้องหลัง: งานที่รอดำเนินการ งานที่กำลังดำเนินการ และงานที่ล้มเหลว',
    'ExtrasDesc'                          => 'เปิดใช้งาน ปิดใช้งาน และกำหนดค่า SimpleRisk Extras (ส่วนเสริมแบบชำระเงิน)',
    'ArtificialIntelligenceExtraDesc'     => 'ส่วนเสริมปัญญาประดิษฐ์ (Artificial Intelligence Extra) ช่วยเพิ่มการวิเคราะห์ความเสี่ยง (รวมถึงการประเมิน FAIR) และจัดทำเอกสารตามความต้องการเฉพาะ',
    'CustomizationExtraDesc'              => 'ส่วนเสริมการปรับแต่ง (Customization Extra) ช่วยให้สามารถเพิ่มและลบฟิลด์ประเภทต่างๆ และสร้างเทมเพลตหน้าเว็บแบบกำหนดเองได้แบบไดนามิก',
    'NotificationExtraDesc'               => 'ส่วนเสริมการแจ้งเตือนทางอีเมลช่วยให้ SimpleRisk สามารถส่งการแจ้งเตือนทางอีเมลเมื่อมีการส่ง แก้ไข หรือดำเนินการใดๆ เกี่ยวกับความเสี่ยง ส่วนเสริมนี้ยังสามารถเพิ่มเป็นสคริปต์ที่กำหนดเวลาไว้เพื่อส่งการแจ้งเตือนเป็นประจำเมื่อความเสี่ยงพร้อมสำหรับการตรวจสอบโดยผู้บริหาร ในผลิตภัณฑ์ SimpleRisk Core หากไม่มีส่วนเสริมนี้ จะไม่มีการแจ้งเตือนใดๆ ส่งออกไปยังภายนอกเครื่องมือเลย',
    'VulnerabilityManagementExtraDesc'    => 'ส่วนเสริมการจัดการช่องโหว่ (Vulnerability Management Extra) ช่วยให้ลูกค้าสามารถผสานรวมระบบ SimpleRisk เข้ากับ Qualys, Tenable.io หรือ Rapid7 Nexpose/InsightVM และนำเข้าข้อมูลทั้งสินทรัพย์และช่องโหว่เข้าสู่ SimpleRisk จากนั้น คุณสามารถเลือกไซต์ที่ต้องการครอบคลุม กำหนดคะแนนช่องโหว่ที่ควรนำเข้า และจัดลำดับความสำคัญของช่องโหว่ที่จะเปลี่ยนเป็นความเสี่ยงเพื่อติดตามได้',
    'IncidentManagementExtraDesc'         => 'ส่วนเสริมการจัดการเหตุการณ์ (Incident Management Extra) อ้างอิงจากคู่มือการจัดการเหตุการณ์ด้านความปลอดภัยคอมพิวเตอร์ NIST 800-61 และมอบความสามารถในการจัดการเหตุการณ์จากภายในระบบ SimpleRisk',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'เปลี่ยนชื่อคำศัพท์ของ SimpleRisk (เช่น ความเสี่ยง สินทรัพย์ กรอบการทำงาน ฯลฯ) ในส่วนติดต่อผู้ใช้ทั้งหมด',
    'RiskConfigurationDesc'               => 'กำหนดค่ากฎการให้คะแนนความเสี่ยง: ระดับ ความต้องการ เกณฑ์ SLA และสูตรความเสี่ยงแบบคลาสสิก/แบบมีส่วนร่วม',
    'RiskAndThreatCatalogDesc'            => 'ดูแลรักษารายการค่าความเสี่ยงและภัยคุกคามที่ใช้ในเมนูแบบดรอปดาวน์',
    'AddAndRemoveValuesDesc'              => 'จัดการค่าในเมนูแบบดรอปดาวน์สำหรับช่องข้อมูลความเสี่ยง: สถานที่ แหล่งที่มา หมวดหมู่ ทีม เทคโนโลยี และอื่นๆ',
    'AssetValuationDesc'                  => 'กำหนดค่ามาตราส่วนการประเมินมูลค่าสินทรัพย์และการแก้ไขการประเมินมูลค่าสินทรัพย์แต่ละรายการ',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'เพิ่ม แก้ไข ปิดใช้งาน และรีเซ็ตผู้ใช้ จัดการนโยบายรหัสผ่าน',
    'RoleManagementDesc'                  => 'กำหนดบทบาทและสิทธิ์ที่แต่ละบทบาทมอบให้',
    'TeamManagementDesc'                  => 'สร้างและจัดการทีมที่ใช้สำหรับการกรองการมองเห็นข้อมูล',
    'SeparationExtraDesc'                 => 'ส่วนเสริมการแยกตามทีมจะจำกัดการดูความเสี่ยงให้เฉพาะผู้ใช้ที่เป็นสมาชิกของทีมที่ได้รับมอบหมายความเสี่ยงนั้นเท่านั้น ในผลิตภัณฑ์ SimpleRisk Core หากไม่มีส่วนเสริมนี้ ผู้ใช้ทุกคนจะสามารถเห็นความเสี่ยงทั้งหมดได้',
    'CustomAuthenticationExtraDesc'       => 'ส่วนเสริมการตรวจสอบสิทธิ์แบบกำหนดเอง (Custom Authentication Extra) รองรับการตรวจสอบสิทธิ์ผ่าน Active Directory และ SAML ในผลิตภัณฑ์ SimpleRisk Core หากไม่มีส่วนเสริมนี้ ตัวเลือกเดียวคือการสร้างผู้ใช้ใหม่ในคลังข้อมูลประจำตัวของ SimpleRisk',
    'EncryptionExtraDesc'                 => 'ฟังก์ชัน Encrypted Database Extra จะสร้างคีย์เข้ารหัส AES-256 บิตแบบสุ่ม จากนั้นใช้คีย์นั้นในการเข้ารหัสข้อความสำคัญก่อนที่จะแทรกเข้าไปในฐานข้อมูล SimpleRisk ซึ่งจะป้องกันไม่ให้ใครสามารถดูหรือแก้ไขข้อมูลได้โดยไม่ใช้แอปพลิเคชัน SimpleRisk โดยตรง',
    'OrganizationManagementDesc'          => "ส่วนเสริมลำดับชั้นองค์กรช่วยให้สามารถกำหนดหน่วยธุรกิจได้หลายหน่วย ซึ่งสามารถรวมทีมได้หลายทีม จากนั้นผู้ใช้สามารถได้รับการกำหนดให้ทำงานในทีมหนึ่งหรือหลายทีมภายใต้หน่วยธุรกิจต่างๆ ซึ่งจะมีผลต่อความสามารถของผู้ใช้ในการดูและใช้งานทีม ผู้ใช้ และสินทรัพย์ที่ตนเองไม่ได้เกี่ยวข้องด้วย",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'การลบข้อมูลจำนวนมากมีความเสี่ยง โปรดใช้อย่างระมัดระวัง เพราะการลบข้อมูลนั้นเป็นการถาวร',
    'AuditTrailDesc'                      => 'ค้นหาและส่งออกบันทึกการตรวจสอบระบบของการกระทำของผู้ใช้',
    'ImportExportExtraDesc'               => 'ฟังก์ชัน Import-Export Extra ช่วยให้คุณสามารถนำเข้าข้อมูลเข้าสู่ SimpleRisk โดยการจับคู่ฟิลด์ในไฟล์ CSV กับฟิลด์ในฐานข้อมูล SimpleRisk สามารถใช้เพื่อนำเข้าผลการตรวจสอบจากสเปรดชีตของบุคคลที่สาม ผลการสแกนช่องโหว่จากเครื่องมืออื่น ทรัพย์สินจาก CMDB ของคุณ และอื่นๆ อีกมากมาย นอกจากนี้ ฟังก์ชัน Extra ยังช่วยให้สามารถส่งออกไฟล์ CSV จาก SimpleRisk ที่มีข้อมูลเกี่ยวกับความเสี่ยง การลดความเสี่ยง การตรวจสอบ หรือรายงานแบบผสมผสานของทั้งสามอย่างได้',
    'JiraExtraDesc'                       => 'Jira Integration Extra ช่วยให้ผู้ใช้สามารถผสานการทำงานแบบสองทิศทางกับระบบ Jira ได้ โดยสามารถเชื่อมโยงความเสี่ยงกับปัญหาใน Jira รวมถึงซิงค์ข้อมูล สถานะ และความคิดเห็นต่างๆ ได้',
    'APIExtraDesc'                        => 'API Extra ช่วยให้ลูกค้าสามารถใช้ RESTful API เพื่อสร้างปฏิสัมพันธ์แบบสคริปต์กับแอปพลิเคชันอื่นๆ เพื่อให้ได้ระบบอัตโนมัติขั้นสูงและใช้ประโยชน์จากโครงสร้างพื้นฐานที่มีอยู่',
    'AdvancedSearchExtraDesc'             => "ฟังก์ชันการค้นหาขั้นสูงเพิ่มเติม (Advanced Search Extra) ขยายขีดความสามารถของช่องค้นหาบนแถบด้านบน เพื่อให้สามารถค้นหาความเสี่ยงโดยการค้นหาข้อความในข้อมูลความเสี่ยงได้",
    'AssessmentsExtraDesc'                => 'ส่วนเสริมการประเมินความเสี่ยง (Risk Assessment Extra) ช่วยให้ผู้ใช้สามารถกำหนดผู้ติดต่อ สร้างคำถาม (รวมถึงตรรกะ) รวบรวมคำถามหลายข้อโดยใช้แม่แบบแบบสอบถาม สร้างแบบสอบถามและส่งไปยังผู้ติดต่อ ดูผลลัพธ์ของแบบสอบถาม เพิ่มความเสี่ยงตามผลลัพธ์เหล่านั้น และเปรียบเทียบผลลัพธ์ในช่วงเวลาต่างๆ นำเข้าและส่งออกการประเมินที่ปรับแต่งจากภายนอก และตรวจสอบเส้นทางการตรวจสอบการประเมินความเสี่ยง',
    'ActiveAssessmentsDesc'               => 'ดูและจัดการการประเมินผลที่กำลังดำเนินการอยู่',
    'WorkflowsExtraDesc'                  => 'Workflows Extra เป็นเครื่องมือจัดการเวิร์กโฟลว์แบบภาพที่ขับเคลื่อนด้วยเหตุการณ์ ซึ่งจะช่วยดำเนินการจัดการความเสี่ยงโดยอัตโนมัติเพื่อตอบสนองต่อเหตุการณ์ต่างๆ ภายใน SimpleRisk คุณสามารถออกแบบเวิร์กโฟลว์ที่จะเริ่มทำงานเมื่อมีการเปลี่ยนแปลง เช่น การส่ง การอัปเดต หรือการตรวจสอบความเสี่ยง เพื่อส่งต่อการอนุมัติ มอบหมายงาน และทำให้กระบวนการดำเนินต่อไปโดยไม่ต้องมีการแทรกแซงด้วยตนเอง',

    // Configure Hub - tile descriptions (frameworks category)
    'UCFExtraDesc'                        => 'Unified Compliance Framework (UCF) Extra คือการผสานรวมระดับ API ระหว่าง Unified Compliance Framework และ SimpleRisk การเปิดใช้งานจะช่วยให้คุณสามารถนำเข้าเฟรมเวิร์กที่เลือกและแมปปิ้งควบคุมได้โดยตรงจาก UCF',
    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extra คือการผสานรวมโดยตรงระหว่าง Secure Controls Framework และ SimpleRisk โดยจะนำเข้าแคตตาล็อกของการควบคุมและแผนที่การจับคู่ของ SCF กับกรอบงานด้านการปฏิบัติตามกฎระเบียบและความปลอดภัยทางไซเบอร์ที่หลากหลาย เข้าสู่ฟังก์ชันการกำกับดูแลของ SimpleRisk เพื่อให้คุณสามารถนำกรอบงานที่ต้องการมาใช้และจัดการการควบคุมได้โดยไม่ต้องสร้างด้วยตนเอง",

