    'SoaChooseFramework' => 'เลือกกรอบงาน',
    'SoaChooseFrameworkHint' => 'คำแถลงเกี่ยวกับความเหมาะสมในการใช้งานจะเขียนขึ้นสำหรับกรอบการทำงานทีละกรอบ',
    // The picker has a roster but nothing in it. Distinct from "this framework
