    'SoaNoControlsHint' => 'กำหนดการควบคุมต่างๆ ลงในกรอบงาน และคำชี้แจงเกี่ยวกับขอบเขตการใช้งานจะแสดงรายการการควบคุมเหล่านั้น',

    // The second half of the statement-of-applicability launcher's affordance
